'use strict';
/* The experience layer only presents engine state. Scene acknowledgements never advance time. */
const exUI={all:localStorage.getItem('vestkyst-all-tools')==='on',sound:localStorage.getItem('vestkyst-sound')==='on',scene:null,audio:null,shown:0,section:'quests'};
const exText=v=>esc(v==null?'':v);
const exArr=v=>Array.isArray(v)?v:[];
const exDays=n=>exText(n)+' '+(Number(n)===1?'dag':'dager');
const exGet=(fn,...args)=>{try{return typeof G[fn]==='function'?G[fn](...args):null;}catch(_){return null;}};
const exGo=(target,label,cls='button ghost')=>`<button class="${cls}" data-view="${exText(target)}">${exText(label)}</button>`;
const exPortrait=(i=0)=>`<div class="ex-face ex-face-${i%4}">${G.contactPortrait?.(G.storyContacts?.[i]?.id)||portrait(i)}</div>`;
const exSpeakerPortrait=id=>`<div class="ex-face">${G.contactPortrait?.(id)||portrait(9)}</div>`;
function exTradeHint(){if(s.ended||s.rankLevel!==0||s.trip||s.event||s.stock.some(n=>n>0)||(s.crime?.attempts||0)<3)return '';return `<aside class="ex-trade-hint"><span class="section-kicker">RAGGEN SER AT DU GÅR I RING</span><h3>Ei småjobb. Så et større trekk.</h3><p>Gjentatte jobber gir mindre betalt og mer søkelys. Se om du har råd til et lite parti fra utlandet. Varene selger du hjemme i Stavanger; reise, innkjøp og risiko vises før du velger.</p><button class="button ghost" data-ex-first-trade>Se innkjøpsreisene →</button></aside>`;}
function exSound(){if(!exUI.sound)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const ctx=exUI.audio||(exUI.audio=new AC());ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(330,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(490,ctx.currentTime+.12);g.gain.setValueAtTime(.025,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.2);o.connect(g).connect(ctx.destination);o.start();o.stop(ctx.currentTime+.21);}catch(_){}}
function exMoves(){return exArr(exGet('nextMoves',s)).slice(0,3);}
function exMoveCard(m,i){return `<article class="ex-move ${i===0?'ex-move-primary':''}"><span class="ex-step">0${i+1}</span><div><span class="section-kicker">${i===0?'DITT NESTE TREKK':'EN ANNEN VEI'}</span><h3>${exText(m.title)}</h3><p>${exText(m.text)}</p><button class="button ${i===0?'brass':'ghost'}" data-ex-move="${i}" ${m.disabled?'disabled':''}>${exText(m.label||'Gjør trekket')} <span aria-hidden="true">→</span></button>${m.reason?`<small>${exText(m.reason)}</small>`:''}</div></article>`;}
function exRankProgress(){const level=s.rankLevel||0,next=G.LEVELS?.[level+1];if(s.ended)return '';if(!next)return `<section class="ex-rank-progress"><span class="section-kicker">${exText(G.rank(s))} / RANGEN ER NÅDD</span><p>Nå er det nettverket, folkene og arven som står på spill.</p></section>`;if(level===4){const requirements=exArr(exGet('godfatherRequirements',s)),met=requirements.filter(r=>r.ok).length,percent=requirements.length?Math.round(met/requirements.length*100):0;return `<section class="ex-rank-progress"><div class="between"><span class="section-kicker">NESTE RANG / ${exText(next.name)}</span><b>${met} av ${requirements.length} krav · ${percent} %</b></div>${meter(percent)}<div class="ex-rank-gates">${requirements.map(r=>`<p class="${r.ok?'profit':''}">${r.ok?'✓':'○'} ${exText(r.name)}</p>`).join('')}</div></section>`;}const worth=Math.max(0,exGet('netWorth',s)||0),percent=Math.min(100,Math.floor(worth/next.worth*100));return `<section class="ex-rank-progress"><div class="between"><span class="section-kicker">NESTE RANG / ${exText(next.name)}</span><b>${percent} % av formuekravet</b></div>${meter(percent)}<p>${kr(worth)} av ${kr(next.worth)} i netto formue.${worth<next.worth?' Mangler '+kr(next.worth-worth)+'.':''}</p></section>`;}
function exEnding(){const o=exGet('outcome',s)||{},arc=exGet('arcInfo',s),quests=exArr(exGet('questList',s)),history=quests.filter(q=>exArr(q.history).length),done=quests.filter(q=>q.status==='done').length,relation=s.story?.relationships?.raggen,goal=typeof goals!=='undefined'?goals[s.goal]?.[0]:null;const lines=[`${s.name||'Skipperen'} kom tilbake til Vågen som ${G.rank(s)}. ${s.crew.members} folk står igjen på laget, og ${s.cities.length} ${s.cities.length===1?'by bærer':'byer bærer'} spor av nettverket.`,relation>0?'Raggen har fortsatt nummeret ditt. '+(relation>=3?'Nøkkelen betyr mer enn døra den åpner.':'Dere har noe å snakke om når regnet kommer.') :relation<0?'Raggen vet hvem du er blitt. Verkstedet husker også prisen folk betalte.':`${s.districts.length} områder og ${s.businesses.length} virksomheter er skrevet inn i byens historie.`,arc?.ending?.text||'Det siste oppgjøret med Bjørnar og Haugland er ikke nedtegnet i denne runden.',history.length?`${done} av kontaktenes historier ble fullført. ${exArr(s.items?.owned).length} gjenstander ble med deg hjem; valgene underveis står igjen i minnene.`:'De gamle oppgjørene er bevart. Denne runden har ingen nedtegnede samtaler fra kontaktenes nyere historier.'];if(s.ownership){const own=exGet('ownershipInfo',s),companies=exArr(own?.projects).filter(p=>p.level>0);if(companies.length)lines.push(companies.length+' virksomheter fikk nye eiere. '+companies.filter(p=>p.path==='partners').length+' drives med lokale medeiere; '+companies.filter(p=>p.path==='control').length+' drives under din kontroll. Avtalene og rivalenes svar er bevart i Eierbordet.');}if(s.legacyFund?.id){const f=exGet('legacyFundInfo',s);lines.push((f?.choice?.name||'Et løfte til byen')+': '+kr(s.legacyFund.paid)+' tilhører nå de andre. '+(s.legacyFund.active?'Løftet ble holdt til siste natt.':'Innbetalingene ble satt på pause; det som allerede ble gitt, ble værende.'));}return `<article class="ex-ending-paper"><div class="ex-newspaper-masthead"><span>VÅGENS SISTE SIDE</span><span>31. DESEMBER 2036</span></div><span class="section-kicker">TI ÅR I STAVANGER / ${exText(G.rank(s))}</span><h1>${o.won?'ET NAVN SOM<br>BLE IGJEN.':'BYEN HUSKER<br>HELE PRISEN.'}</h1><p class="ex-ending-deck">${exText(goal||'Arven din')} · ${o.won?'Målet ble nådd.':'Målet ble ikke nådd.'} Runden er avsluttet.</p><div class="ex-ending-portrait"><div class="ex-face ex-player-face">${portrait(Math.max(0,Math.min(8,s.rankLevel||0)))}</div><span>${exText(s.name)} / ${exText(G.rank(s))}</span></div><div class="ex-epilogue">${lines.map(line=>`<p>${exText(line)}</p>`).join('')}</div><div class="ex-ending-facts"><span>Folk igjen <b>${s.crew.members}</b></span><span>Byer <b>${s.cities.length}</b></span><span>Netto formue <b>${kr(exGet('netWorth',s)||0)}</b></span></div><div class="ex-ending-actions"><button class="button brass" data-next-mode="standard">Ny standardrunde…</button><button class="button ghost" data-next-mode="dynasty">Ny arverunde…</button>${exGo('ledger','Les oppgjørene')}</div><details class="ex-ending-report"><summary>Det fullstendige sluttbildet</summary>${typeof endReport==='function'?endReport():''}${exGo('scaling','Se imperiet og arven')}${history.length?`<h2>Det dere husker.</h2>${history.map(q=>`<button class="button ghost" data-ex-quest="${exText(q.id)}">${exText(q.title)} · ${exArr(q.history).length} valg →</button>`).join('')}`:''}</details></article>`;}
function exQuestCards(limit){const list=exArr(exGet('questList',s)).slice().sort((a,b)=>({active:0,locked:1,done:2}[a.status]??1)-({active:0,locked:1,done:2}[b.status]??1));return list.slice(0,limit||list.length).map((q,i)=>exQuest(q,i)).join('');}
function exContactName(id){return exArr(G.storyContacts).find(c=>c.id===id)?.name||id||'En kontakt';}
function exItemName(id){const items=G.QUEST_ITEMS||G.ITEMS||G.ITEM_DEFS||{};return (Array.isArray(items)?items.find(x=>x.id===id):items[id])?.name||id;}
function exQuest(q,i){if(s.ended)return `<article class="ex-quest"><span class="section-kicker">HISTORIEN ER AVSLUTTET</span><h3>${exText(q.title)}</h3><p>${exArr(q.history).length?exArr(q.history).length+' valg er bevart fra denne historien.':'Denne runden har ingen nedtegnede valg fra dette oppdraget.'}</p>${exArr(q.history).length?`<button class="button ghost" data-ex-quest="${exText(q.id)}">Les minnene →</button>`:''}</article>`;const info=exGet('questInfo',s,q.id)||q,step=info.current||info;return `<article class="ex-quest"><div class="ex-quest-top"><span class="section-kicker">${exText(exContactName(info.contact))}</span><span class="ex-status">${exText(info.status==='done'?'Fullført':info.status==='locked'?'Et senere spor':info.ready?'Klar for ditt valg':'På sporet')}</span></div><h3>${exText(step.title||info.title||q.title)}</h3><p>${exText(step.text||info.intro)}</p>${step.objective?`<div class="ex-objective">↳ ${exText(step.objective)}</div>`:''}${exQuestDetails(info)}<button class="button ghost" data-ex-quest="${exText(q.id)}" ${info.status!=='done'&&!info.ready?'disabled':''}>${info.status==='done'?'Se saken':info.status==='locked'?'Åpner som '+(G.LEVELS[info.rank]?.name||'rang '+info.rank):!info.ready?'Bygg forutsetningene først':'Les og velg'} →</button></article>`;}
function exQuestDetails(q){const step=q.current||q,items=exArr(step.choices).map(c=>c.item).filter(Boolean);return `${q.total?`<p class="ex-progress-text">Spor ${Math.min(q.total,(q.step||0)+1)} av ${q.total}</p>${meter(Math.max(0,(q.step||0))/q.total*100)}`:''}${items.length?`<div class="ex-reward"><span>ET OBJEKT MED EN HISTORIE</span><b>${exText([...new Set(items)].map(exItemName).join(' / '))}</b></div>`:''}${q.reason&&!q.ready?`<p class="small">${exText(q.reason)}</p>`:''}`;}
function exContactLink(c){const quests=exArr(exGet('questList',s)),direct=quests.filter(q=>q.contact===c.id||q.current?.speaker===c.id),related=quests.filter(q=>exArr(G.QUEST_LINES).find(l=>l.id===q.id)?.steps.some(step=>step.speaker===c.id||step.choices.some(x=>x.contact===c.id))),list=direct.length?direct:related;return list.slice().sort((a,b)=>(a.status==='active'?0:a.status==='locked'?1:2)-(b.status==='active'?0:b.status==='locked'?1:2))[0]||null;}
function exContactGate(c,q){if(s.ended)return q&&exArr(q.history).length?null:'Historien er avsluttet. Ingen nye møter venter.';if((c.id==='bjornar'||c.id==='haugland')&&exGet('arcInfo',s)?.active)return null;if(!q)return 'Et nytt møte åpner senere i historien.';if(q.status==='locked')return 'Møtet åpner som '+(G.LEVELS[q.rank]?.name||'rang '+q.rank)+'.';if(q.status==='done')return null;if(!q.ready)return q.reason||q.current?.objective||'Følg sporet videre.';if(q.contact===c.id||q.current?.speaker===c.id)return null;return 'Neste møte etter «'+(q.current?.title||q.title)+'». '+(q.current?.objective||q.reason||'Følg oppdraget videre.');}
function exContacts(limit=4){const contacts=exArr(G.storyContacts);return contacts.slice(0,limit).map((c,i)=>{const q=exContactLink(c),gate=exContactGate(c,q);return `<button class="ex-contact" data-ex-contact="${exText(c.id||i)}" ${gate?'disabled':''}>${exPortrait(i)}<span><b>${exText(c.name)}</b><small>${exText(c.role||'Kontakt i Stavanger')}${s.story?.relationships?.[c.id]!=null?' · forhold '+(s.story.relationships[c.id]>0?'+':'')+exText(s.story.relationships[c.id]):''}</small><em>${exText(gate||c.voice)}</em>${q?`<span class="ex-contact-hook">${exText(q.status==='done'?'Se det dere gjorde sammen':q.current?.title||q.title)} ${gate?'':'→'}</span>`:''}</span><strong aria-hidden="true">${gate?'⌁':'↗'}</strong></button>`;}).join('');}
function exOpenContact(id){const c=exArr(G.storyContacts).find(c=>c.id===id);if(!c)return;const q=exContactLink(c),gate=exContactGate(c,q);if(gate)return;const arc=!s.ended&&(c.id==='bjornar'||c.id==='haugland')&&exGet('arcInfo',s)?.active;modal(`<div class="ex-contact-dialog">${exPortrait(exArr(G.storyContacts).indexOf(c))}<span class="section-kicker">${exText(c.role)}</span><h2>${exText(c.name)}</h2><p>«${exText(c.voice)}»</p><p>${exText(c.bio)}</p>${q?`<div class="ex-contact-thread"><span class="section-kicker">${exText(q.title)}</span><h3>${exText(q.current?.title||'Historien dere deler')}</h3><p>${exText(q.current?.objective||q.intro)}</p>${q.reason&&q.status!=='done'?`<p>${exText(q.reason)}</p>`:''}<button class="button brass" data-ex-quest="${exText(q.id)}" ${!s.ended&&q.status!=='done'&&!q.ready?'disabled':''}>${s.ended||q.status==='done'?'Les det som skjedde':'Åpne samtalen'} →</button></div>`:''}${arc?'<button class="button ghost" data-ex-section="arc">Ta det siste oppgjøret →</button>':''}</div>`);}
const exPlaces=G.PLACES;
function exPlaceQuote(h){let reason=null,detail='';if(h.kind==='quest'){const q=exGet('questInfo',s,h.id);reason=!q?'Oppdraget er ikke tilgjengelig.':q.status==='locked'?q.reason:q.status!=='done'&&!q.ready?q.reason:null;detail=q?.current?.objective||q?.intro||'';}else if(h.kind==='crime'){const q=exGet('crimeQuote',s,h.id);reason=q?.reason||(!q?'Jobben er ikke tilgjengelig.':null);detail=q?Math.round(q.success*100)+' % suksess · '+exDays(q.days)+' · '+kr(q.reward)+' ved suksess':'';}else if(h.kind==='arc'){const a=exGet('arcInfo',s);reason=!a?.active?'Åpner som Gudfar eller i siste del av tiåret.':null;detail=a?.active?'Bjørnar: '+Math.round(a.rival.pressure)+'/100 press · saken: '+Math.round(a.case.evidence)+'/100 bevis':'';}else if(h.kind==='sell'){reason=!exArr(s.stock).some(n=>n>0)?'Kofferten er tom. Fullfør en innkjøpsreise først.':null;detail='Se dagens etterspørsel og oppgjøret før du selger.';}else if(h.kind==='buy'){detail='Velg land, varer, pris og faktisk reisetid.';}else if(h.kind==='rest'){detail='3 dager · +35 utholdenhet · +25 nerver · −6 søkelys · ukedrift løper.';}else if(h.view==='cities'){detail='Les kravene for hver by før du etablerer deg.';}if(s.ended&&h.kind!=='view')reason='Runden er avsluttet.';else if(s.trip&&!['view','quest','arc'].includes(h.kind))reason='Fullfør reisen først.';else if(s.event&&!['view','quest','arc'].includes(h.kind))reason='Ta den viktige avgjørelsen først.';return {reason,detail};}
function exPlaceCard(p,i){const options=p.hooks.map(exPlaceQuote),open=options.some(o=>!o.reason);return `<article class="ex-place ${open?'':'ex-place-locked'}"><span class="ex-place-sign" aria-hidden="true">${exText(p.symbol)}</span><div><span class="section-kicker">${String(i+1).padStart(2,'0')} / ${exText(p.district)}</span><h3>${exText(p.name)}</h3><p>${exText(p.text)}</p><span class="ex-place-now">${exText(open?p.hooks[options.findIndex(o=>!o.reason)].label:options[0]?.reason)}</span><button class="button ${open?'ghost':'locked'}" data-ex-place="${exText(p.id)}" ${open?'':'disabled'}>${open?'Gå dit og velg':'Ikke tilgjengelig ennå'} ${open?'→':''}</button></div></article>`;}
function exPlacePanel(){return `<section class="ex-places"><div class="ex-section-title"><div><span class="section-kicker">${exPlaces.length} STEDER / ETT VALG OM GANGEN</span><h2>Hvor går du?</h2></div></div><p class="ex-place-intro">Et besøk åpner konkrete valg. Å se seg rundt bruker ingen spilltid; pris og dager står ved handlingen du velger.</p><div class="ex-place-grid">${exPlaces.map(exPlaceCard).join('')}</div></section>`;}
function exVisit(id){const p=exPlaces.find(p=>p.id===id);if(!p)return;modal(`<div class="ex-visit"><span class="section-kicker">${exText(p.district)} / DU ER HER</span><h2>${exText(p.name)}</h2><p>${exText(p.text)}</p><div class="ex-visit-choices">${p.hooks.map((h,i)=>{const q=exPlaceQuote(h);return `<article><h3>${exText(h.label)}</h3><p>${exText(q.detail)}</p>${q.reason?`<p class="ex-gate">${exText(q.reason)}</p>`:''}<button class="button ${q.reason?'ghost':'brass'}" data-ex-place-action="${exText(p.id)}" data-ex-place-option="${i}" ${q.reason?'disabled':''}>${q.reason?'Forutsetning mangler':h.kind==='rest'?'Hent deg inn · 3 dager':'Se og velg'} →</button></article>`;}).join('')}</div><small>Du har ikke brukt tid ved å åpne dette stedet.</small></div>`);}
function exDoPlace(id,index){const p=exPlaces.find(p=>p.id===id),h=p?.hooks[index];if(!h||exPlaceQuote(h).reason)return;$('#dialog').close();if(h.kind==='quest')exOpenQuest(h.id);else if(h.kind==='crime')exOpenCrime(h.id);else if(h.kind==='buy')countries();else if(h.kind==='sell')sellMarket();else if(h.kind==='rest')act('crimeRest');else if(h.kind==='arc')exSection('arc');else if(h.kind==='view'){view=h.view;render();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}}
function exSection(section){if(!['quests','places','crime','arc'].includes(section))section='quests';exUI.section=section;view='experience';if($('#dialog').open)$('#dialog').close();render();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function exArc(){if(s.ended)return '';const a=exGet('arcInfo',s);if(!a||!a.active)return '';return `<section class="ex-threat"><div class="ex-threat-symbol" aria-hidden="true">!</div><div><span class="section-kicker">BYEN SVARER / ${exDays(a.daysLeft).toUpperCase()} IGJEN</span><h2>${exText(a.title)}</h2><p>${exText(a.ending?.text||`${a.rival.name} presser nettverket ditt. ${a.case.name} følger sporene.`)}</p><div class="ex-arc-counts"><span>Rivalpress ${Math.round(a.rival.pressure)}/100</span><span>Bevis ${Math.round(a.case.evidence)}/100</span><span>Frist ${exText(a.closingDate)}</span><span>Akt ${exText(a.act||1)} av ${exText(a.maxActs||3)}</span>${a.control!=null?`<span>Kontroll ${Math.round(a.control)}/100</span>`:''}${a.nextActIn!=null?`<span>Neste akt om ${exDays(a.nextActIn)}</span>`:''}</div></div>${view==='experience'?'':'<button class="button ghost" data-ex-section="arc">Åpne siste akt →</button>'}</section>${view==='experience'?`${exArr(a.obligations).length?`<div class="ex-arc-obligations"><h3>Det avtalene koster videre.</h3>${exArr(a.obligations).map(o=>`<p><b>${exText(o.label)}</b> ${exText(o.text)}</p>`).join('')}<p>Betalt hittil: ${kr(a.obligationPaid||0)}</p></div>`:''}<div class="ex-arc-options">${[...exArr(a.preparations),...exArr(a.options)].map((o,i)=>`<article class="ex-arc-option"><h3>${exText(o.label)}</h3><p>${exText(o.text)}</p>${o.crewLossSuccess!=null?`<p>Medlemmer som forlater laget: ${exText(o.crewLossSuccess)} ved suksess, inntil ${exText(o.crewLossFailure)} ved nederlag.</p>`:''}${o.choice==='challenge'?'<p>Et tapt oppgjør kan koste ytterligere 8 % av kassa.</p>':''}<p>${kr(o.cost||0)} · ${exDays(o.days)}${o.success!=null?' · '+Math.round(o.success*100)+' % sjanse':''}</p>${o.reason?`<p>${exText(o.reason)}</p>`:''}<button class="button ghost" data-ex-arc="${i}" ${o.valid===false?'disabled':''}>${exText(o.label)} →</button></article>`).join('')}</div>`:''}`;}
const exPriorHome=home;
home=function(){if(s.ended)return exEnding()+exHomeTools();const moves=exMoves();return `<div class="ex-home"><section class="ex-hero"><div class="harbor-image"></div><div class="ex-rain" aria-hidden="true"></div><div class="ex-hero-content"><span class="section-kicker">VÅGEN / ${exText(G.rank(s))} / ${s.rankLevel>=5?'SISTE AKT · '+((s.arc?.phase||0)+1):'DIN VEI OPP'}</span><h1>${s.ended?'BYEN HUSKER<br>VALGENE DINE.':'ET NAVN.<br>NOE Å MISTE.'}</h1><p>${s.ended?'Historien din ligger igjen i gatene. Se hva du bygde, og hvem som ble med deg.':'Regnet gir seg ikkje. Det gjør ikkje byen heller. Hvem ringer du, og hva setter du på spill?'}</p><div class="scene-buttons">${exGo('experience',s.ended?'Se historien din':'Finn et oppdrag','button brass')}${exGo('routes','Til kaien','button glass')}</div></div><div class="ex-live"><i></i> STAVANGER LEVER VIDERE</div></section>${exRankProgress()}${exTradeHint()}<section class="ex-next"><div class="ex-section-title"><div><span class="section-kicker">DU BESTEMMER TEMPOET</span><h2>Ka gjør du nå?</h2></div><span>Tre veier videre. Ett valg om gangen.</span></div><div class="ex-moves">${moves.length?moves.map(exMoveCard).join(''):`<article class="ex-move"><div><h3>Byen venter på deg.</h3><p>Ta en prat på gata, eller gå til kaien og planlegg første handel.</p>${exGo('experience','Møt kontaktene','button brass')}</div></article>`}</div></section><section class="ex-city-invite"><div><span class="section-kicker">STAVANGER / ${exPlaces.length} STEDER Å GÅ</span><h2>Du kjenner kaien. Ka med resten?</h2><p>Verkstedet, kjøkkenbordet, tårnet. Folk og muligheter har en adresse.</p></div><button class="button ghost" data-ex-section="places">Ut i byen →</button></section><section class="street-strip"><div><span class="section-kicker">FOTFESTE / STAVANGER</span><h2>Bygg et navn i gatene.</h2><p>${s.districts.length} av 5 områder. Et lokalt nettverk åpner veien videre.</p></div><div class="street-signs">${G.DISTRICTS.map((d,i)=>`<button data-act="district" data-arg="${i}" class="street-sign ${s.districts.includes(i)?"owned":""}" ${s.ended||s.event||s.trip||s.districts.includes(i)||s.cash<d.cost?"disabled":""}><span>${s.districts.includes(i)?"I NETTVERKET":kr(d.cost)}</span>${exText(d.name)}<small>${kr(d.income)} / uke før drift</small></button>`).join("")}</div></section><div class="ex-story-grid"><section><div class="ex-section-title"><div><span class="section-kicker">FOLK HAR LANGE MINNER</span><h2>På linja.</h2></div>${exGo('experience','Alle spor ↗','text-button')}</div><div class="ex-contacts">${exContacts()||`<div class="ex-contact">${exPortrait(0)}<span><b>Raggen</b><small>Din kontakt på kaien</small><em>«Du kan ikkje stå her resten av livet.»</em></span></div>`}</div></section><section><div class="ex-section-title"><div><span class="section-kicker">HISTORIEN DIN</span><h2>Uferdige saker.</h2></div></div><div class="ex-quests">${exQuestCards(2)||mission()}</div></section></div>${exArc()}${exObjects()}${exHomeTools()}<section class="ex-recent"><span class="section-kicker">DET BYEN HUSKER</span>${exArr(s.log).slice(0,2).map(t=>`<p>↳ ${exText(t)}</p>`).join('')||'<p>Det første trekket er ditt.</p>'}</section></div>`;};
function exHomeTools(){return `<details class="ex-inventory-tools"><summary>Varer, hjemmelager og økonomi</summary>${typeof depot==="function"?depot():""}<div class="market-actions">${btn("rest","","Ligg lavt ei uke",s.ended||!!s.event||!!s.trip,"button ghost")}${btn("shift","","Ta et skift · 3 500 kr før drift",s.ended||!!s.event||!!s.trip,"button ghost")}</div></details>`;}
function exObjects(){const owned=exArr(s.items?.owned);return owned.length?`<section class="ex-objects"><div class="ex-section-title"><div><span class="section-kicker">TING DU HAR FORTJENT</span><h2>Det du tar med deg.</h2></div></div><div class="ex-object-grid">${owned.map(id=>{const item=G.QUEST_ITEMS?.[id];return `<article><span aria-hidden="true">◇</span><h3>${exText(item?.name||id)}</h3><p>${exText(item?.text)}</p>${Object.entries(item?.modifiers||{}).map(([k,v])=>`<small>${exText(({income:'Lokalinntekt',travelCost:'Reisekostnad',heatGain:'Søkelys',trainingCost:'Treningskostnad',salePrice:'Salgspris',routeReliability:'Rutepålitelighet'})[k]||k)} ${v>1?'+':''}${Math.round((v-1)*100)} %</small>`).join('')}</article>`;}).join('')}</div></section>`:'';}
function exWorld(){if(s.ended)return '';const w=exGet('worldInfo',s);if(!w)return '';return `<section class="ex-world"><details ${w.pending?'open':''}><summary><span><span class="section-kicker">BYEN UTENFOR DØRA</span><strong>${exText(w.pending?.title||w.title||'Nora følger med på byen.')}</strong></span><span>${w.pending?'Et valg venter':'Se kalenderen →'}</span></summary><p>${exText(w.pending?.text||'La Nora håndtere de vanlige endringene, eller be om å ta valgene selv.')}</p>${w.pending?`<div class="ex-dialog-choices">${exArr(w.pending.choices).map((c,i)=>`<button class="choice" data-ex-world-choice="${i}" ${c.valid===false?'disabled':''}>${exText(c.label)}<small>${kr(c.cost||0)} · ${exDays(c.days||1)}</small>${c.reason?`<small>${exText(c.reason)}</small>`:''}</button>`).join('')}</div>`:''}<div class="ex-world-policy"><span class="section-kicker">OPPFØLGING / ${exText(w.policy)}</span>${exArr(w.policies).map((p,i)=>`<button class="button ghost" data-ex-world-policy="${i}" ${p.id===w.policy?'aria-pressed="true"':'aria-pressed="false"'}>${exText(p.label)}${p.id===w.policy?' ✓':''}</button>`).join('')}</div>${exArr(w.upcoming).slice(0,1).map(e=>`<p class="ex-world-upcoming"><b>Neste vindu: ${exText(e.title)}</b><span>${exText(e.fact)}</span></p>`).join('')}</details></section>`;}
function exStory(){if(s.ended)return `<div class="ex-story ex-archive">${exEnding()}<section class="ex-quests">${exQuestCards()}</section>${exObjects()}</div>`;const section=exUI.section,arc=exGet('arcInfo',s);return `<div class="ex-story"><div class="page-title"><div><span class="section-kicker">KONTAKTER / ${exPlaces.length} STEDER / DINE VALG</span><h1>GATA HAR<br>ALLTID ET SVAR.</h1><p>Velg hvem du stoler på, hvor du går og hva du setter på spill.</p></div>${exGo('home','← Tilbake til Vågen')}</div><div class="ex-section-tabs" role="group" aria-label="Velg hva du vil gjøre">${[['quests','Oppdrag'],['places','Byen · '+exPlaces.length+' steder'],['crime','Jobber på gata'],['arc','Siste akt']].map(([id,label])=>`<button data-ex-section="${id}" class="${section===id?'selected':''}" aria-pressed="${section===id}" ${id==='arc'&&!arc?.active?'disabled':''}>${label}</button>`).join('')}</div>${section==='places'?exPlacePanel():section==='crime'?`<section><h2 class="section-heading">En sjanse på gata.</h2><div class="ex-crime-grid">${exCrimes()}</div></section>`:section==='arc'?exArc():`<div class="ex-story-grid"><section><h2 class="section-heading">Saker som venter.</h2><div class="ex-quests">${exQuestCards()||'<article class="ex-quest"><h3>Ingen uløste saker akkurat nå.</h3><p>Ta neste trekk fra Vågen.</p></article>'}</div></section><section><h2 class="section-heading">Folk på linja.</h2><div class="ex-contacts">${exContacts(99)}</div>${exWorld()}</section></div>${exObjects()}`}</div>`;}
function exCrimes(){if(s.ended)return '<p>Ingen nye jobber venter. Historien er avsluttet.</p>';const stats=s.crime;return `${exTradeHint()}${stats?`<div class="ex-crime-terms"><span>Utholdenhet <b>${Math.round(stats.stamina)}/100</b></span><span>Nerver <b>${Math.round(stats.nerve)}/100</b></span></div><button class="button ghost" data-act="crimeRest">Hent deg inn · 3 dager →</button>`:''}${exArr(exGet('crimeList',s)).map(q=>`<article class="ex-crime"><span class="section-kicker">GATA / NIVÅ ${exText(q.level)}</span><h3>${exText(q.name)}</h3><p>${exText(q.text)}</p><div class="ex-crime-terms"><span>Suksess <b>${Math.round(q.success*100)} %</b></span><span>Tid <b>${exDays(q.days)}</b></span><span>Belønning <b>${kr(q.reward)}</b></span></div><p class="small">${exText(q.reason||`${q.stamina} utholdenhet · ${q.nerve} nerver · ${kr(q.cost)} innsats`)}</p><button class="button ghost" data-ex-crime="${exText(q.id)}" ${q.valid===false?'disabled':''}>Se risiko og belønning →</button></article>`).join('')}`;}
function exOpenQuest(id){const q=exGet('questInfo',s,id);if(!q)return;if(s.ended){modal(`<span class="section-kicker">MINNER FRA EN AVSLUTTET RUNDE</span><h2>${exText(q.title)}</h2><div class="ex-history">${exArr(q.history).length?exArr(q.history).map(h=>`<p>✓ ${exText(h.title)}<small>${exText(h.label)} · dag ${exText(h.day)}</small></p>`).join(''):'<p>Ingen samtaler er nedtegnet fra dette oppdraget i denne runden.</p>'}</div>`);return;}const step=q.current||q;modal(`<span class="section-kicker">${exText(exContactName(step.speaker||q.contact))} / ${exText(q.title)}</span><h2>${exText(step.title||q.title)}</h2><p>${exText(step.text||q.intro)}</p>${step.objective?`<div class="ex-objective">${exText(step.objective)}</div>`:''}${exQuestDetails(q)}${q.status==='done'?`<div class="ex-history">${exArr(q.history).map(h=>`<p>✓ ${exText(h.title)}<small>${exText(h.label)} · dag ${exText(h.day)}</small></p>`).join('')}</div>`:''}<div class="ex-dialog-choices">${exArr(step.choices).map((c,i)=>`<button class="choice" data-ex-quest-choice="${exText(id)}" data-ex-choice="${exText(c.id??i)}" ${!q.ready||c.allowed===false?'disabled':''}>${exText(c.label)}<small>${exDays(c.days||0)} · ${kr(c.cost||0)} innsats${c.relation?' · forhold '+(c.relation>0?'+':'')+exText(c.relation):''}${c.heat?' · søkelys '+(c.heat>0?'+':'')+exText(c.heat):''}${c.loyalty?' · lojalitet '+(c.loyalty>0?'+':'')+exText(c.loyalty):''}${c.influence?' · innflytelse '+(c.influence>0?'+':'')+exText(c.influence):''}${c.cash?' · '+kr(c.cash)+' i belønning':''}${c.item?' · '+exText(exItemName(c.item)):''}</small>${c.reason?`<small>${exText(c.reason)}</small>`:''}</button>`).join('')}</div>`);}
function exOpenCrime(id){const q=exGet('crimeQuote',s,id);if(!q)return;modal(`<span class="section-kicker">ET BEVISST VALG / STAVANGER</span><h2>${exText(q.name)}</h2><p>${exText(q.text)}</p><div class="ex-crime-terms"><span>Suksess <b>${Math.round(q.success*100)} %</b></span><span>Komplikasjon <b>${Math.round(q.complication*100)} %</b></span><span>Kritisk utfall <b>${Math.round(q.critical*100)} %</b></span></div><div class="ex-crime-terms"><span>Tid <b>${exDays(q.days)}</b></span><span>Innsats <b>${kr(q.cost)}</b></span><span>Ved suksess <b>${kr(q.reward)}</b></span></div><p>${exText(q.stamina)} utholdenhet og ${exText(q.nerve)} nerver. Komplikasjoner og kritiske utfall kan koste penger, søkelys og folk.${q.crewRisk?' Folk fra laget er utsatt.':''} Ved komplikasjon: ${kr(q.complicationReward||0)} i utbetaling. Et kritisk utfall koster totalt ${kr(q.criticalLoss||0)} inkludert innsats.</p>${q.reason?`<p>${exText(q.reason)}</p>`:''}<div class="ex-dialog-choices"><button class="button brass" data-ex-crime-start="${exText(id)}" ${q.valid===false?'disabled':''}>Ta sjansen →</button><button class="button ghost" data-ex-close>La det ligge</button></div>`);}
if(!nav.some(n=>n[0]==='experience'))nav.splice(1,0,['experience','02','Gata']);
nav.forEach((n,i)=>n[1]=String(i+1).padStart(2,'0'));
const exPriorRender=render;
render=function(){const current=view;if(current==='experience')view='home';exPriorRender();view=current;if(current==='experience')$('#screen').innerHTML=exStory();const navEl=$('#nav');navEl.querySelectorAll('[data-view]').forEach(n=>{const active=n.dataset.view===current;n.classList.toggle('active',active);if(active)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');const basic=['home','experience','routes','crew','rivals'].includes(n.dataset.view);n.hidden=!exUI.all&&!basic&&!active;});navEl.insertAdjacentHTML('beforeend',`${exGet('pendingScene',s)?'<button data-ex-inbox>'+(s.ended?'Arkiv · ':'Meldinger ● ')+exArr(s.experience?.scenes).length+'</button>':''}<button class="ex-all-tools" data-ex-all aria-expanded="${exUI.all}">${exUI.all?'Færre valg −':'Vis alle +'}<span>${nav.length} visninger</span></button>`);const version=document.querySelector('footer>span');if(version)version.textContent='VESTKYST / SPILLBAR ALFA 0.10';document.body.classList.add('experience-on');document.body.classList.toggle('ex-all-visible',exUI.all);document.body.classList.toggle('ex-ended',!!s.ended);$('#policy').disabled=!!s.ended;if(s.ended){$('#event').innerHTML='';document.querySelectorAll('main [data-act],main [data-edit-route],main [data-fight],main [data-release],main [data-project-kind],main [data-store],main #newRoute,main #newRouteEmpty,main #buyAbroad,main #sellStreet').forEach(b=>{b.disabled=true;b.title='Runden er avsluttet.';});}exRenderUpdates();};
const exUpdates=document.createElement('section');exUpdates.id='experienceUpdates';exUpdates.setAttribute('aria-label','Meldinger fra byen');$('#screen').before(exUpdates);
const exIsOutcome=x=>/result|outcome|ending|crime|warning/i.test(x.kind)||/result/i.test(x.id);
function exSceneReceipt(scene){const ended=s.ended,quest=scene.quest&&exGet('questInfo',s,scene.quest),canAnswer=!ended&&quest?.ready;return `<article class="ex-inline-receipt"><div class="ex-receipt-speaker">${exSpeakerPortrait(scene.speaker)}<span class="section-kicker">${exText(exContactName(scene.speaker||'Byen'))}</span></div><div><span class="section-kicker">${exIsOutcome(scene)?'DETTE BLE FØLGENE':ended?'EN BEVART MELDING':'PÅ LINJA'}</span><h2>${exText(scene.title)}</h2><p>${exText(scene.text)}</p>${exIsOutcome(scene)&&scene.day===s.day&&s.summary?`<div class="ex-outcome-receipt"><span>${exDays(s.summary.days||0)} senere</span><b>${s.summary.net>=0?'+':''}${kr(s.summary.net||0)} i kassa</b><small>Inkluderer driften mens tiden gikk.</small></div>`:''}${scene.item?`<div class="ex-scene-object"><h3>◇ ${exText(exItemName(scene.item))}</h3><p>${exText(G.QUEST_ITEMS?.[scene.item]?.text||'')}</p></div>`:''}${exArr(scene.lines).map(l=>`<p>${exText(typeof l==='object'?l.text:l)}</p>`).join('')}<div class="ex-receipt-actions">${canAnswer?`<button class="button ghost" data-ex-scene-quest="${exText(scene.quest)}" data-ex-scene-id="${exText(scene.id)}">Åpne samtalen →</button>`:''}<button class="text-button" data-ex-scene-dismiss="${exText(scene.id)}">Lest · legg bort</button></div></div></article>`;}
function exRenderUpdates(){const scenes=exArr(s.experience?.scenes);if(!scenes.length){exUpdates.innerHTML='';return;}const newestDay=Math.max(...scenes.map(x=>x.day)),currentScenes=scenes.filter(x=>x.day===newestDay),latest=currentScenes.slice().reverse().find(exIsOutcome)||currentScenes[0],shown=exUI.inbox?scenes.slice().reverse():s.ended?[]:[latest];exUpdates.innerHTML=`${exUI.inbox?`<div class="ex-inbox-title"><h2>${s.ended?'Meldingsarkivet.':'Meldinger fra byen.'}</h2><button class="text-button" data-ex-inbox>Lukk innboksen</button></div>`:''}${shown.map(exSceneReceipt).join('')}${!exUI.inbox&&scenes.length>1?`<button class="text-button" data-ex-inbox>${s.ended?'Les bevarte meldinger i arkivet':'Se '+scenes.length+' meldinger i innboksen'} →</button>`:''}`;}
function exDismiss(id){if(id!=null&&typeof G.dismissScene==='function'){G.dismissScene(s,id);save();}render();}
function exQueueScene(){exRenderUpdates();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-ex-first-trade')){countries();return;}if(b.hasAttribute('data-ex-world-choice')&&!s.ended){const w=exGet('worldInfo',s),c=exArr(w?.pending?.choices)[+b.dataset.exWorldChoice];if(c&&c.valid!==false)act(c.action,c.arg);}if(b.hasAttribute('data-ex-world-policy')&&!s.ended){const w=exGet('worldInfo',s),p=exArr(w?.policies)[+b.dataset.exWorldPolicy];if(p)act(p.action,p.arg);}if(b.hasAttribute('data-ex-section'))exSection(b.dataset.exSection);if(b.hasAttribute('data-ex-place'))exVisit(b.dataset.exPlace);if(b.hasAttribute('data-ex-place-action'))exDoPlace(b.dataset.exPlaceAction,+b.dataset.exPlaceOption);if(b.hasAttribute('data-ex-all')){exUI.all=!exUI.all;localStorage.setItem('vestkyst-all-tools',exUI.all?'on':'off');render();}if(b.hasAttribute('data-ex-move')){const m=exMoves()[Number(b.dataset.exMove)];if(!m||m.disabled||s.ended&&m.action)return;exSound();if(m.ui==='buy'){countries();return;}if(m.ui==='sell'){sellMarket();return;}if(m.action)act(m.action,m.arg);if(m.view){if(m.view==='experience'){exUI.section=m.arg?.section==='crime'?'crime':m.arg?.section==='arc'?'arc':'quests';}view=m.view;render();if(m.arg?.quest){exOpenQuest(m.arg.quest);} window.scrollTo({top:0,behavior:'smooth'});}}if(b.hasAttribute('data-ex-contact'))exOpenContact(b.dataset.exContact);if(b.hasAttribute('data-ex-quest'))exOpenQuest(b.dataset.exQuest);if(b.hasAttribute('data-ex-quest-choice')&&!s.ended){act('questChoice',{quest:b.dataset.exQuestChoice,choice:b.dataset.exChoice});$('#dialog').close();exQueueScene();}if(b.hasAttribute('data-ex-crime'))exOpenCrime(b.dataset.exCrime);if(b.hasAttribute('data-ex-crime-start')&&!s.ended){$('#dialog').close();exSound();act('crimeAttempt',b.dataset.exCrimeStart);}if(b.hasAttribute('data-ex-arc')&&!s.ended){const a=exGet('arcInfo',s),o=[...exArr(a?.preparations),...exArr(a?.options)][+b.dataset.exArc];if(o&&o.valid!==false)act(o.action,o.arg);}if(b.hasAttribute('data-ex-inbox')){exUI.inbox=!exUI.inbox;exRenderUpdates();if(exUI.inbox)exUpdates.scrollIntoView({block:'start',behavior:'auto'});}if(b.hasAttribute('data-ex-scene-dismiss'))exDismiss(b.dataset.exSceneDismiss);if(b.hasAttribute('data-ex-close'))$('#dialog').close();if(b.hasAttribute('data-ex-scene-quest')){const id=b.dataset.exSceneQuest;exDismiss(b.dataset.exSceneId);exOpenQuest(id);}});
const exPriorSettings=$('#settings').onclick;
$('#settings').onclick=()=>{exPriorSettings();$('#dialogBody').insertAdjacentHTML('beforeend',`<hr><label class="check-label"><input id="exSoundToggle" type="checkbox" ${exUI.sound?'checked':''}> Diskrete lyder ved egne valg</label><p class="small">Valgfritt. Ingen musikk. Du kan slå av når som helst.</p>`);$('#exSoundToggle').onchange=e=>{exUI.sound=e.target.checked;localStorage.setItem('vestkyst-sound',exUI.sound?'on':'off');exSound();};};
render();
